/// url = 'https://genomde.de/fhir/StructureMap/EngineQuirkQ1bare'
/// name = 'EngineQuirkQ1bare'
/// title = 'Engine probe: fml-edit-safe quirk Q1 Q1 bare where-not-equal (4.0.12 NPE; 4.1.21 evaluates it correctly)'
/// status = 'draft'

uses "https://genomde.de/fhir/StructureDefinition/DatenkranzOncology" alias Datenkranz as source
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group main(source src : Datenkranz, target pat : Patient) {
  src.metaData as md then Md(md, pat) "md";
}

group Md(source md, target pat : Patient) {
  md.gender as g where g != 'female' -> pat.identifier as id, id.system = 'urn:q1:bare', id.value = g "bare";
  md.gender as g where g != 'male' -> pat.identifier as id, id.system = 'urn:q1:bare-must-not-fire', id.value = g "bare-false";
}
